function nbTrain(docs){ var clsCount={}, vocab={}, featCount={};
  docs.forEach(function(d){ clsCount[d.cls]=(clsCount[d.cls]||0)+1; var seen={}; d.feats.forEach(function(f){ seen[f]=1; vocab[f]=1; });
    Object.keys(seen).forEach(function(f){ featCount[d.cls]=featCount[d.cls]||{}; featCount[d.cls][f]=(featCount[d.cls][f]||0)+1; }); });
  var V=Object.keys(vocab).length, total=docs.length, classes=Object.keys(clsCount), model={classes:classes, prior:{}, cond:{}, V:V, total:total};
  classes.forEach(function(c){ model.prior[c]=clsCount[c]/total; model.cond[c]={}; var fc=featCount[c]||{}; var denom=clsCount[c]+V;
    Object.keys(vocab).forEach(function(f){ model.cond[c][f]=((fc[f]||0)+1)/denom; }); });
  return model; }
function nbScore(model,feats){ var res={}; model.classes.forEach(function(c){ var s=Math.log(model.prior[c]||1e-12);
  feats.forEach(function(f){ var p=model.cond[c][f]; if(p===undefined) p=1/(model.V+model.total); s+=Math.log(p); }); res[c]=s; }); return res; }
function nbPredict(model,feats){ var sc=nbScore(model,feats), best=null,bv=-Infinity; for(var c in sc) if(sc[c]>bv){bv=sc[c];best=c;} return best; }
var EXPORTS={nbTrain:nbTrain, nbScore:nbScore, nbPredict:nbPredict};

